</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC (built exactly as listed)
   surface V(x,y)          → PlaneGeometry(6.4,5.2,140,110) reshaped, vertexColors, MeshLambert DoubleSide
   flat reference sheet    → same mesh where |V|<~0.1  (light cornflower #8fc0e8)
   peak (+q, right)        → same mesh, V clamped at +1.25 → flat circular cap
   pit  (-q, left)         → same mesh, V clamped at -1.25 → flat circular floor
   contour rings (16)      → LineSegments (marching squares on V grid) #1b1b2a
   V = 0 symmetry line     → LineSegments (marching squares at level 0) #8899aa
   bounding box            → LineSegments from EdgesGeometry(BoxGeometry(6.4,2.8,5.2)) #9a9a9a
   lights                  → AmbientLight + DirectionalLight
*/

/* ── field / grid parameters ─────────────────────────────────────────────── */
const NX = 141, NZ = 111;
const X0 = -3.2, X1 = 3.2, Z0 = -2.6, Z1 = 2.6;
const DX = (X1 - X0) / (NX - 1), DZ = (Z1 - Z0) / (NZ - 1);
const KC = 0.55, ASPH2 = 0.22 * 0.22, CLAMPV = 1.25;

const gx = (i) => X0 + i * DX;
const gz = (j) => Z1 - j * DZ;

let qMinus = -1.0;       // chargeBalance
let sep = 2.6;           // chargeSeparation
let morph = 1.0, morphTarget = 1.0;
let viewMode = 'Surface + contours';

const Vg = new Float32Array(NX * NZ);

function fieldAt(x, z) {
  const rp = Math.sqrt((x - sep / 2) * (x - sep / 2) + z * z + ASPH2);
  const rm = Math.sqrt((x + sep / 2) * (x + sep / 2) + z * z + ASPH2);
  return KC * (1 / rp + qMinus / rm);
}

function computeField() {
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) {
      Vg[j * NX + i] = fieldAt(gx(i), z);
    }
  }
}

/* ── lights ──────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.72));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.55);
dirLight.position.set(3.5, 6.0, 4.0);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.22);
dirLight2.position.set(-4, 3, -3);
scene.add(dirLight2);

/* ── colour ramp (height based) ──────────────────────────────────────────── */
const RAMP = [
  [0.00, 0x8f / 255, 0xc0 / 255, 0xe8 / 255],
  [0.20, 0xa9 / 255, 0xd0 / 255, 0xf0 / 255],
  [0.50, 0xb1 / 255, 0x8f / 255, 0xd8 / 255],
  [0.80, 0xe8 / 255, 0xa8 / 255, 0xc8 / 255],
  [1.00, 0xf5 / 255, 0xe0 / 255, 0xe8 / 255]
];
function rampColor(v, out) {
  let s = Math.min(1, Math.abs(v) / CLAMPV);
  let k = 0;
  while (k < RAMP.length - 2 && s > RAMP[k + 1][0]) k++;
  const a = RAMP[k], b = RAMP[k + 1];
  const t = (s - a[0]) / (b[0] - a[0] || 1);
  out[0] = a[1] + (b[1] - a[1]) * t;
  out[1] = a[2] + (b[2] - a[2]) * t;
  out[2] = a[3] + (b[3] - a[3]) * t;
}

/* ── surface mesh ────────────────────────────────────────────────────────── */
const surfGeom = new THREE.PlaneGeometry(X1 - X0, Z1 - Z0, NX - 1, NZ - 1);
const surfColors = new Float32Array(NX * NZ * 3);
surfGeom.setAttribute('color', new THREE.BufferAttribute(surfColors, 3));
const surfMat = new THREE.MeshLambertMaterial({
  vertexColors: true,
  side: THREE.DoubleSide,
  polygonOffset: true,
  polygonOffsetFactor: 1,
  polygonOffsetUnits: 1
});
const surfMesh = new THREE.Mesh(surfGeom, surfMat);
scene.add(surfMesh);

const _c = [0, 0, 0];
function updateSurface(updateColors) {
  const pos = surfGeom.attributes.position;
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) {
      const n = j * NX + i;
      let v = Vg[n];
      if (v > CLAMPV) v = CLAMPV; else if (v < -CLAMPV) v = -CLAMPV;
      pos.setXYZ(n, gx(i), v * morph, z);
      if (updateColors) {
        rampColor(v, _c);
        surfColors[3 * n] = _c[0];
        surfColors[3 * n + 1] = _c[1];
        surfColors[3 * n + 2] = _c[2];
      }
    }
  }
  pos.needsUpdate = true;
  if (updateColors) surfGeom.attributes.color.needsUpdate = true;
  surfGeom.computeVertexNormals();
  surfGeom.computeBoundingSphere();
  surfGeom.computeBoundingBox();
}

/* ── contour lines (marching squares) ────────────────────────────────────── */
const MAXV = 200000;
const cPos = new Float32Array(MAXV * 3);
const cBaseY = new Float32Array(MAXV);
let cCount = 0;

const zPos = new Float32Array(8000 * 3);
const zBaseY = new Float32Array(8000);
let zCount = 0;

const contourGeom = new THREE.BufferGeometry();
contourGeom.setAttribute('position', new THREE.BufferAttribute(cPos, 3));
const contourLines = new THREE.LineSegments(
  contourGeom, new THREE.LineBasicMaterial({ color: 0x1b1b2a })
);
scene.add(contourLines);

const zeroGeom = new THREE.BufferGeometry();
zeroGeom.setAttribute('position', new THREE.BufferAttribute(zPos, 3));
const zeroLine = new THREE.LineSegments(
  zeroGeom, new THREE.LineBasicMaterial({ color: 0x8899aa })
);
scene.add(zeroLine);

const NLEV = 16;
const LEVELS = [];
for (let i = 0; i < NLEV; i++) LEVELS.push(-1.2 + i * (2.4 / (NLEV - 1)));

function marchLevel(level, arr, baseArr, startIdx, y) {
  let n = startIdx;
  for (let j = 0; j < NZ - 1; j++) {
    const za = gz(j), zb = gz(j + 1);
    for (let i = 0; i < NX - 1; i++) {
      const v00 = Vg[j * NX + i], v10 = Vg[j * NX + i + 1];
      const v11 = Vg[(j + 1) * NX + i + 1], v01 = Vg[(j + 1) * NX + i];
      let mn = v00, mx = v00;
      if (v10 < mn) mn = v10; if (v10 > mx) mx = v10;
      if (v11 < mn) mn = v11; if (v11 > mx) mx = v11;
      if (v01 < mn) mn = v01; if (v01 > mx) mx = v01;
      if (level < mn || level > mx) continue;

      const xa = gx(i), xb = gx(i + 1);
      const px = [], pz = [];
      // bottom edge v00-v10
      if ((v00 - level) * (v10 - level) < 0) {
        const t = (level - v00) / (v10 - v00);
        px.push(xa + (xb - xa) * t); pz.push(za);
      } else { px.push(NaN); pz.push(NaN); }
      // right edge v10-v11
      if ((v10 - level) * (v11 - level) < 0) {
        const t = (level - v10) / (v11 - v10);
        px.push(xb); pz.push(za + (zb - za) * t);
      } else { px.push(NaN); pz.push(NaN); }
      // top edge v11-v01
      if ((v11 - level) * (v01 - level) < 0) {
        const t = (level - v11) / (v01 - v11);
        px.push(xb + (xa - xb) * t); pz.push(zb);
      } else { px.push(NaN); pz.push(NaN); }
      // left edge v01-v00
      if ((v01 - level) * (v00 - level) < 0) {
        const t = (level - v01) / (v00 - v01);
        px.push(xa); pz.push(zb + (za - zb) * t);
      } else { px.push(NaN); pz.push(NaN); }

      const valid = [];
      for (let e = 0; e < 4; e++) if (!Number.isNaN(px[e])) valid.push(e);
      let pairs = null;
      if (valid.length === 2) pairs = [[valid[0], valid[1]]];
      else if (valid.length === 4) {
        const centre = (v00 + v10 + v11 + v01) * 0.25;
        pairs = centre > level ? [[0, 1], [2, 3]] : [[0, 3], [1, 2]];
      }
      if (!pairs) continue;
      for (const [e1, e2] of pairs) {
        if (n + 2 > MAXV) return n;
        arr[3 * n] = px[e1]; arr[3 * n + 1] = y; arr[3 * n + 2] = pz[e1];
        baseArr[n] = level; n++;
        arr[3 * n] = px[e2]; arr[3 * n + 1] = y; arr[3 * n + 2] = pz[e2];
        baseArr[n] = level; n++;
      }
    }
  }
