/* ELEMENT SPEC (built exactly as listed)
   surface V(x,y)          → PlaneGeometry(6.4,5.2,140,110) reshaped, vertexColors, MeshLambert DoubleSide
   flat reference sheet    → same mesh where |V|<~0.1  (light cornflower #8fc0e8)
   peak (+q, right)        → same mesh, V clamped at +1.25 → flat circular cap
   pit  (-q, left)         → same mesh, V clamped at -1.25 → flat circular floor
   contour rings (16)      → LineSegments (marching squares on V grid) #1b1b2a
   V = 0 symmetry line     → LineSegments (marching squares at level 0) #8899aa
   bounding box            → LineSegments from EdgesGeometry(BoxGeometry(6.4,2.8,5.2)) #9a9a9a
   lights                  → AmbientLight + DirectionalLight
*/

/* ── field / grid parameters ─────────────────────────────────────────────── */
const NX = 141, NZ = 111;
const X0 = -3.2, X1 = 3.2, Z0 = -2.6, Z1 = 2.6;
const DX = (X1 - X0) / (NX - 1), DZ = (Z1 - Z0) / (NZ - 1);
const KC = 0.55, ASPH2 = 0.22 * 0.22, CLAMPV = 1.25;

const gx = (i) => X0 + i * DX;
const gz = (j) => Z1 - j * DZ;

let qMinus = -1.0;       // chargeBalance
let sep = 2.6;           // chargeSeparation
let morph = 1.0, morphTarget = 1.0;
let viewMode = 'Surface + contours';

const Vg = new Float32Array(NX * NZ);

function fieldAt(x, z) {
  const rp = Math.sqrt((x - sep / 2) * (x - sep / 2) + z * z + ASPH2);
  const rm = Math.sqrt((x + sep / 2) * (x + sep / 2) + z * z + ASPH2);
  return KC * (1 / rp + qMinus / rm);
}

function computeField() {
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) {
      Vg[j * NX + i] = fieldAt(gx(i), z);
    }
  }
}

/* ── lights ──────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.72));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.55);
dirLight.position.set(3.5, 6.0, 4.0);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.22);
dirLight2.position.set(-4, 3, -3);
scene.add(dirLight2);

/* ── colour ramp (height based) ──────────────────────────────────────────── */
const RAMP = [
  [0.00, 0x8f / 255, 0xc0 / 255, 0xe8 / 255],
  [0.20, 0xa9 / 255, 0xd0 / 255, 0xf0 / 255],
  [0.50, 0xb1 / 255, 0x8f / 255, 0xd8 / 255],
  [0.80, 0xe8 / 255, 0xa8 / 255, 0xc8 / 255],
  [1.00, 0xf5 / 255, 0xe0 / 255, 0xe8 / 255]
];
function rampColor(v, out) {
  let s = Math.min(1, Math.abs(v) / CLAMPV);
  let k = 0;
  while (k < RAMP.length - 2 && s > RAMP[k + 1][0]) k++;
  const a = RAMP[k], b = RAMP[k + 1];
  const t = (s - a[0]) / (b[0] - a[0] || 1);
  out[0] = a[1] + (b[1] - a[1]) * t;
  out[1] = a[2] + (b[2] - a[2]) * t;
  out[2] = a[3] + (b[3] - a[3]) * t;
