  const pos = surfGeom.attributes.position;
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) {
      const n = j * NX + i;
      let v = Vg[n];
      if (v > CLAMPV) v = CLAMPV; else if (v < -CLAMPV) v = -CLAMPV;
      pos.setXYZ(n, gx(i), v * morph, z);
      if (updateColors) {
        rampColor(v, _c);
        surfColors[3 * n] = _c[0];
        surfColors[3 * n + 1] = _c[1];
        surfColors[3 * n + 2] = _c[2];
      }
