  pos.needsUpdate = true;
  if (updateColors) surfGeom.attributes.color.needsUpdate = true;
  surfGeom.computeVertexNormals();
  surfGeom.computeBoundingSphere();
  surfGeom.computeBoundingBox();
}

/* ── contour lines (marching squares) ────────────────────────────────────── */
const MAXV = 200000;
const cPos = new Float32Array(MAXV * 3);
const cBaseY = new Float32Array(MAXV);
let cCount = 0;

const zPos = new Float32Array(8000 * 3);
const zBaseY = new Float32Array(8000);
