scene.add(zeroLine);

const NLEV = 16;
const LEVELS = [];
for (let i = 0; i < NLEV; i++) LEVELS.push(-1.2 + i * (2.4 / (NLEV - 1)));

function marchLevel(level, arr, baseArr, startIdx, y) {
  let n = startIdx;
  for (let j = 0; j < NZ - 1; j++) {
    const za = gz(j), zb = gz(j + 1);
    for (let i = 0; i < NX - 1; i++) {
      const v00 = Vg[j * NX + i], v10 = Vg[j * NX + i + 1];
      const v11 = Vg[(j + 1) * NX + i + 1], v01 = Vg[(j + 1) * NX + i];
      let mn = v00, mx = v00;
      if (v10 < mn) mn = v10; if (v10 > mx) mx = v10;
      if (v11 < mn) mn = v11; if (v11 > mx) mx = v11;
      if (v01 < mn) mn = v01; if (v01 > mx) mx = v01;
      if (level < mn || level > mx) continue;

      const xa = gx(i), xb = gx(i + 1);
      const px = [], pz = [];
      // bottom edge v00-v10
      if ((v00 - level) * (v10 - level) < 0) {
        const t = (level - v00) / (v10 - v00);
        px.push(xa + (xb - xa) * t); pz.push(za);
      } else { px.push(NaN); pz.push(NaN); }
      // right edge v10-v11
      if ((v10 - level) * (v11 - level) < 0) {
        const t = (level - v10) / (v11 - v10);
        px.push(xb); pz.push(za + (zb - za) * t);
      } else { px.push(NaN); pz.push(NaN); }
      // top edge v11-v01
      if ((v11 - level) * (v01 - level) < 0) {
        const t = (level - v11) / (v01 - v11);
        px.push(xb + (xa - xb) * t); pz.push(zb);
      } else { px.push(NaN); pz.push(NaN); }
      // left edge v01-v00
      if ((v01 - level) * (v00 - level) < 0) {
        const t = (level - v01) / (v00 - v01);
        px.push(xa); pz.push(zb + (za - zb) * t);
      } else { px.push(NaN); pz.push(NaN); }

      const valid = [];
      for (let e = 0; e < 4; e++) if (!Number.isNaN(px[e])) valid.push(e);
      let pairs = null;
      if (valid.length === 2) pairs = [[valid[0], valid[1]]];
      else if (valid.length === 4) {
        const centre = (v00 + v10 + v11 + v01) * 0.25;
        pairs = centre > level ? [[0, 1], [2, 3]] : [[0, 3], [1, 2]];
      }
      if (!pairs) continue;
      for (const [e1, e2] of pairs) {
        if (n + 2 > MAXV) return n;
        arr[3 * n] = px[e1]; arr[3 * n + 1] = y; arr[3 * n + 2] = pz[e1];
        baseArr[n] = level; n++;
        arr[3 * n] = px[e2]; arr[3 * n + 1] = y; arr[3 * n + 2] = pz[e2];
        baseArr[n] = level; n++;
      }
    }
  }
  return n;
}

function updateContours() {
  cCount = 0;
  for (const L of LEVELS) {
    if (Math.abs(L) < 1e-6) continue;
    cCount = marchLevel(L, cPos, cBaseY, cCount, L * morph + 0.012);
  }
  contourGeom.attributes.position.needsUpdate = true;
  contourGeom.setDrawRange(0, cCount);
  contourGeom.computeBoundingSphere();

  zCount = marchLevel(0, zPos, zBaseY, 0, 0.014);
  zeroGeom.attributes.position.needsUpdate = true;
  zeroGeom.setDrawRange(0, zCount);
  zeroGeom.computeBoundingSphere();
}

function rescaleLines() {
  for (let n = 0; n < cCount; n++) cPos[3 * n + 1] = cBaseY[n] * morph + 0.012;
  contourGeom.attributes.position.needsUpdate = true;
  for (let n = 0; n < zCount; n++) zPos[3 * n + 1] = 0.014;
  zeroGeom.attributes.position.needsUpdate = true;
}

/* ── bounding box wireframe ──────────────────────────────────────────────── */
const boxEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(6.4, 2.8, 5.2)),
  new THREE.LineBasicMaterial({ color: 0x9a9a9a })
);
scene.add(boxEdges);

/* ── build ───────────────────────────────────────────────────────────────── */
computeField();
updateSurface(true);
updateContours();

registerInteractive(surfMesh, {
  title: 'Potential surface V(x, y)',
  tooltip: 'Height = potential. Click for details.',
  body: 'The height of this sheet is the electric potential of two charges on conducting spheres of radius a. ' +
        'Near the positive sphere V → +k q/a, giving a steep hill truncated at the sphere surface; near the negative ' +
        'sphere V → −k q/a, giving the matching funnel. Far away both contributions cancel and the sheet flattens to V = 0. ' +
        'The dark rings are equipotentials: where they crowd together, the field E = −∇V is strong.'
});

/* ── camera ──────────────────────────────────────────────────────────────── */
const ISO_VIEW = { projection: 'orthographic', azimuthDeg: 130, elevationDeg: 27, heightFraction: 0.62 };
const TOP_VIEW = { projection: 'orthographic', azimuthDeg: 90, elevationDeg: 88, heightFraction: 0.62 };
setCameraView(ISO_VIEW);

/* ── labels ──────────────────────────────────────────────────────────────── */
const labPlus = addLabel('+<i>q</i>', new THREE.Vector3(sep / 2, 1.5, 0), { fontSize: '13px', color: '#a03060', bold: true });
const labMinus = addLabel('&minus;<i>q</i>', new THREE.Vector3(-sep / 2, -1.5, 0), { fontSize: '13px', color: '#3060a0', bold: true });
const labZero = addLabel('<i>V</i> = 0', new THREE.Vector3(0, 0.06, Z1 + 0.35), { fontSize: '12px', color: '#66788a' });
const labPeak = addLabel('conducting sphere (flat cap)', new THREE.Vector3(sep / 2, CLAMPV + 0.42, -0.2), { fontSize: '11px', color: '#777' });

function updateLabels() {
  labPlus.pos.set(sep / 2, (CLAMPV + 0.25) * morph + 0.08, 0);
  labMinus.pos.set(-sep / 2, (-CLAMPV - 0.25) * morph - 0.08, 0);
  labZero.pos.set(0, 0.06, Z1 + 0.35);
  labPeak.pos.set(sep / 2, (CLAMPV + 0.42) * morph + 0.1, -0.2);
  labPeak.div.style.opacity = morph > 0.6 ? '1' : '0';
}
updateLabels();

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const elBal = document.getElementById('chargeBalance');
const elSep = document.getElementById('chargeSeparation');
const valBal = document.getElementById('valBal');
const valSep = document.getElementById('valSep');
const btnSurf = document.getElementById('modeSurf');
const btnMap = document.getElementById('modeMap');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function refreshAll() {
  computeField();
  updateSurface(true);
  updateContours();
  updateLabels();
}

function syncReadouts() {
  valBal.textContent = qMinus.toFixed(2);
  valSep.textContent = sep.toFixed(2);
}
syncReadouts();

elBal.addEventListener('input', () => {
  qMinus = parseFloat(elBal.value);
  syncReadouts(); refreshAll();
});
elSep.addEventListener('input', () => {
  sep = parseFloat(elSep.value);
  syncReadouts(); refreshAll();
});

function setMode(name, moveCamera) {
  viewMode = name;
  const flat = (name === 'Contour map only');
  morphTarget = flat ? 0 : 1;
  btnSurf.classList.toggle('active', !flat);
  btnMap.classList.toggle('active', flat);
  boxEdges.visible = !flat;
  if (moveCamera !== false) setCameraView(flat ? TOP_VIEW : ISO_VIEW);
}
btnSurf.addEventListener('click', () => setMode('Surface + contours'));
btnMap.addEventListener('click', () => setMode('Contour map only'));

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1. Equal and opposite charges',
    narration: 'Height is electric potential. The right charge is positive, raising a steep narrow peak; the left charge is equal and negative, carving a matching funnel. Both are truncated at the conducting-sphere surface.',
    state: { chargeBalance: -1, chargeSeparation: 2.6, viewMode: 'Surface + contours' }
  },
  {
    title: '2. Read the contours',
    narration: 'Flatten to the contour map. The rings crowd where the surface was steepest, right at each charge, and spread far apart out on the flat sheet — close contours mean a strong field.',
    state: { chargeBalance: -1, chargeSeparation: 2.6, viewMode: 'Contour map only' }
  },
  {
    title: '3. Bring the charges together',
    narration: 'Reducing the separation pulls hill and trough close; the sheet between them tilts sharply and the loops elongate, showing the intense field in the gap between the spheres.',
    state: { chargeBalance: -1, chargeSeparation: 1, viewMode: 'Surface + contours' }
  },
  {
    title: '4. Unbalance the charges',
    narration: 'Weakening the negative charge shallows the trough while the peak keeps its height, and the zero-potential line shifts toward the weaker charge — sign and magnitude both read directly off the relief.',
    state: { chargeBalance: -0.4, chargeSeparation: 2.6, viewMode: 'Surface + contours' }
  }
];
let stepIdx = 0, tween = null, playTimer = null;

function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  stepText.textContent = s.narration;
  setMode(s.state.viewMode);
  tween = {
    b0: qMinus, s0: sep,
    b1: s.state.chargeBalance, s1: s.state.chargeSeparation,
    t0: performance.now(), dur: 850
  };
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
const btnPlay = document.getElementById('stepPlay');
btnPlay.addEventListener('click', () => {
  if (playTimer) {
    clearInterval(playTimer); playTimer = null;
    btnPlay.textContent = 'Play'; btnPlay.classList.remove('active');
  } else {
    btnPlay.textContent = 'Stop'; btnPlay.classList.add('active');
    goToStep(stepIdx + 1);
    playTimer = setInterval(() => goToStep(stepIdx + 1), 5200);
  }
});
goToStep(0);

/* ── tween / morph loop (separate from scaffold's animate) ───────────────── */
function figLoop() {
  requestAnimationFrame(figLoop);

  if (tween) {
    const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = u * u * (3 - 2 * u);
    qMinus = tween.b0 + (tween.b1 - tween.b0) * e;
    sep = tween.s0 + (tween.s1 - tween.s0) * e;
    elBal.value = qMinus; elSep.value = sep;
    syncReadouts(); refreshAll();
    if (u >= 1) tween = null;
  }

  if (Math.abs(morph - morphTarget) > 0.002) {
    morph += (morphTarget - morph) * 0.14;
    updateSurface(false);
    rescaleLines();
    updateLabels();
  } else if (morph !== morphTarget) {
    morph = morphTarget;
    updateSurface(false);
    rescaleLines();
    updateLabels();
  }
}
figLoop();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

