/* ── field / grid parameters ─────────────────────────────────────────────── */
const NX = 161, NZ = 131;
const NCX = NX - 1, NCZ = NZ - 1;
const X0 = -3.2, X1 = 3.2, Z0 = -2.6, Z1 = 2.6;
const DX = (X1 - X0) / (NX - 1), DZ = (Z1 - Z0) / (NZ - 1);
const KC = 0.55, ASPH2 = 0.22 * 0.22, CLAMPV = 1.25;

const gx = (i) => X0 + i * DX;
const gz = (j) => Z1 - j * DZ;

let qMinus = -1.0;       // chargeBalance
let sep = 2.6;           // chargeSeparation
let morph = 1.0, morphTarget = 1.0;

const Vg = new Float32Array(NX * NZ);
const cellMin = new Float32Array(NCX * NCZ);
const cellMax = new Float32Array(NCX * NCZ);

function fieldAt(x, z) {
  const rp = Math.sqrt((x - sep / 2) * (x - sep / 2) + z * z + ASPH2);
  const rm = Math.sqrt((x + sep / 2) * (x + sep / 2) + z * z + ASPH2);
  return KC * (1 / rp + qMinus / rm);
}

function computeField() {
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) Vg[j * NX + i] = fieldAt(gx(i), z);
  }
  for (let j = 0; j < NCZ; j++) {
    for (let i = 0; i < NCX; i++) {
      const a = Vg[j * NX + i], b = Vg[j * NX + i + 1];
      const c = Vg[(j + 1) * NX + i + 1], e = Vg[(j + 1) * NX + i];
      let mn = a, mx = a;
      if (b < mn) mn = b; if (b > mx) mx = b;
      if (c < mn) mn = c; if (c > mx) mx = c;
      if (e < mn) mn = e; if (e > mx) mx = e;
      cellMin[j * NCX + i] = mn; cellMax[j * NCX + i] = mx;
    }
  }
}

/* ── colour ramp (|V| based) + baked shading ─────────────────────────────── */
const RAMP = [
  [0.00, 0x8f / 255, 0xc0 / 255, 0xe8 / 255],
  [0.18, 0xa9 / 255, 0xd0 / 255, 0xf0 / 255],
  [0.42, 0xb8 / 255, 0xa6 / 255, 0xe0 / 255],
  [0.62, 0xb1 / 255, 0x8f / 255, 0xd8 / 255],
  [0.82, 0xe8 / 255, 0xa8 / 255, 0xc8 / 255],
  [1.00, 0xf5 / 255, 0xe0 / 255, 0xe8 / 255]
