// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC (built exactly as listed)
   surface V(x,y)        → PlaneGeometry(6.4,5.2,160,130) reshaped in place,
                           per-vertex colour = |V| ramp x baked directional shade,
                           MeshBasicMaterial(vertexColors, DoubleSide, polygonOffset)
   flat reference sheet  → same mesh where V~0     saturated cornflower #79b2e4 / #8fc0e8
   peak (+q, right)      → same mesh, V clamped at +1.25 → flat circular cap  pink → #f5e0e8
   pit  (-q, left)       → same mesh, V clamped at -1.25 → flat circular floor, same banding
   contour rings (28)    → LineSegments, marching squares on V grid, y = level     #1b1b2a
   V = 0 symmetry line   → LineSegments, marching squares at level 0               #8899aa
   bounding box          → LineSegments from EdgesGeometry(BoxGeometry(6.4,2.8,5.2)) #9a9a9a
   label leader lines    → LineSegments, 3 segments, #9aa2ab
*/

/* ── field / grid parameters ─────────────────────────────────────────────── */
const NX = 161, NZ = 131;
const NCX = NX - 1, NCZ = NZ - 1;
const X0 = -3.2, X1 = 3.2, Z0 = -2.6, Z1 = 2.6;
const DX = (X1 - X0) / (NX - 1), DZ = (Z1 - Z0) / (NZ - 1);
const KC = 0.55, ASPH2 = 0.22 * 0.22, CLAMPV = 1.25;

const gx = (i) => X0 + i * DX;
const gz = (j) => Z1 - j * DZ;

let qMinus = -1.0;       // chargeBalance
let sep = 2.6;           // chargeSeparation
let morph = 1.0, morphTarget = 1.0;
let annotations = true;

const Vg = new Float32Array(NX * NZ);
const cellMin = new Float32Array(NCX * NCZ);
const cellMax = new Float32Array(NCX * NCZ);

function fieldAt(x, z) {
  const rp = Math.sqrt((x - sep / 2) * (x - sep / 2) + z * z + ASPH2);
  const rm = Math.sqrt((x + sep / 2) * (x + sep / 2) + z * z + ASPH2);
  return KC * (1 / rp + qMinus / rm);
}

function computeField() {
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) Vg[j * NX + i] = fieldAt(gx(i), z);
  }
  for (let j = 0; j < NCZ; j++) {
    for (let i = 0; i < NCX; i++) {
      const a = Vg[j * NX + i], b = Vg[j * NX + i + 1];
      const c = Vg[(j + 1) * NX + i + 1], e = Vg[(j + 1) * NX + i];
      let mn = a, mx = a;
      if (b < mn) mn = b; if (b > mx) mx = b;
      if (c < mn) mn = c; if (c > mx) mx = c;
      if (e < mn) mn = e; if (e > mx) mx = e;
      cellMin[j * NCX + i] = mn; cellMax[j * NCX + i] = mx;
    }
  }
}

/* ── colour ramp (|V| based) + baked shading ─────────────────────────────── */
const RAMP = [
  [0.00, 0x79 / 255, 0xb2 / 255, 0xe4 / 255],
  [0.10, 0x8f / 255, 0xc0 / 255, 0xe8 / 255],
  [0.30, 0xb0 / 255, 0xa4 / 255, 0xe2 / 255],
  [0.55, 0xb1 / 255, 0x8f / 255, 0xd8 / 255],
  [0.78, 0xe8 / 255, 0xa8 / 255, 0xc8 / 255],
  [1.00, 0xf5 / 255, 0xe0 / 255, 0xe8 / 255]
];
const _c = [0, 0, 0];
function rampColor(v, out) {
  const s = Math.min(1, Math.abs(v) / CLAMPV);
  let k = 0;
  while (k < RAMP.length - 2 && s > RAMP[k + 1][0]) k++;
  const a = RAMP[k], b = RAMP[k + 1];
  const t = (s - a[0]) / (b[0] - a[0] || 1);
  out[0] = a[1] + (b[1] - a[1]) * t;
  out[1] = a[2] + (b[2] - a[2]) * t;
  out[2] = a[3] + (b[3] - a[3]) * t;
}
// light from front-left-above: lights the FAR inner wall of the pit so the
// funnel reads as a hollow, not a flat dish.
const LX = -0.46, LY = 0.78, LZ = 0.43;
const LN = Math.sqrt(LX * LX + LY * LY + LZ * LZ);
const lx = LX / LN, ly = LY / LN, lz = LZ / LN;

/* ── surface mesh ────────────────────────────────────────────────────────── */
const surfGeom = new THREE.PlaneGeometry(X1 - X0, Z1 - Z0, NX - 1, NZ - 1);
const surfColors = new Float32Array(NX * NZ * 3);
surfGeom.setAttribute('color', new THREE.BufferAttribute(surfColors, 3));
const surfMat = new THREE.MeshBasicMaterial({
  vertexColors: true,
  side: THREE.DoubleSide,
  polygonOffset: true,
  polygonOffsetFactor: 2,
  polygonOffsetUnits: 2
});
const surfMesh = new THREE.Mesh(surfGeom, surfMat);
scene.add(surfMesh);

function updateSurface() {
  const pos = surfGeom.attributes.position;
  for (let j = 0; j < NZ; j++) {
    const z = gz(j);
    for (let i = 0; i < NX; i++) {
      const n = j * NX + i;
      let v = Vg[n];
      if (v > CLAMPV) v = CLAMPV; else if (v < -CLAMPV) v = -CLAMPV;
      pos.setXYZ(n, gx(i), v * morph, z);
    }
  }
  pos.needsUpdate = true;
  surfGeom.computeVertexNormals();

  const nrm = surfGeom.attributes.normal;
  for (let n = 0; n < NX * NZ; n++) {
    let v = Vg[n];
    if (v > CLAMPV) v = CLAMPV; else if (v < -CLAMPV) v = -CLAMPV;
    rampColor(v, _c);
    let nx = nrm.getX(n), ny = nrm.getY(n), nz = nrm.getZ(n);
    if (ny < 0) { nx = -nx; ny = -ny; nz = -nz; }   // shade the visible (upper) side
    let ndl = nx * lx + ny * ly + nz * lz;
    if (ndl < 0) ndl = 0;
    let shade = 0.66 + 0.40 * ndl;
    if (shade > 1.04) shade = 1.04;
    if (v < 0) shade *= 1 - 0.10 * Math.pow(-v / CLAMPV, 1.4);  // gentle funnel cavity cue
    surfColors[3 * n] = Math.min(1, _c[0] * shade);
    surfColors[3 * n + 1] = Math.min(1, _c[1] * shade);
    surfColors[3 * n + 2] = Math.min(1, _c[2] * shade);
  }
  surfGeom.attributes.color.needsUpdate = true;
  surfGeom.computeBoundingSphere();
  surfGeom.computeBoundingBox();
}

/* ── contour lines (marching squares, drawn ON the surface) ──────────────── */
const MAXV = 260000;
const cPos = new Float32Array(MAXV * 3);
const cLev = new Float32Array(MAXV);
let cCount = 0;

const ZMAX = 16000;
const zPos = new Float32Array(ZMAX * 3);
let zCount = 0;

const contourGeom = new THREE.BufferGeometry();
contourGeom.setAttribute('position', new THREE.BufferAttribute(cPos, 3));
const contourLines = new THREE.LineSegments(
  contourGeom, new THREE.LineBasicMaterial({ color: 0x1b1b2a })
);
contourLines.renderOrder = 2;
scene.add(contourLines);

const zeroGeom = new THREE.BufferGeometry();
zeroGeom.setAttribute('position', new THREE.BufferAttribute(zPos, 3));
const zeroLine = new THREE.LineSegments(
  zeroGeom, new THREE.LineBasicMaterial({ color: 0x8899aa })
);
zeroLine.renderOrder = 2;
scene.add(zeroLine);

// 14 levels per sign → 28 rings: wide loops out on the sheet (0.05, 0.10)
// tightening into a dense band on the steep flanks, as in the source plate.
const HALF_LEVELS = [0.05, 0.10, 0.16, 0.23, 0.31, 0.40, 0.50, 0.61,
  0.72, 0.83, 0.94, 1.05, 1.14, 1.21];
const LEVELS = [];
for (let i = HALF_LEVELS.length - 1; i >= 0; i--) LEVELS.push(-HALF_LEVELS[i]);
for (let i = 0; i < HALF_LEVELS.length; i++) LEVELS.push(HALF_LEVELS[i]);

const _px = [0, 0, 0, 0], _pz = [0, 0, 0, 0], _ok = [false, false, false, false];

function marchLevel(level, arr, levArr, startIdx, y, cap) {
  let n = startIdx;
  for (let j = 0; j < NCZ; j++) {
    const za = gz(j), zb = gz(j + 1);
    for (let i = 0; i < NCX; i++) {
      const ci = j * NCX + i;
      if (level < cellMin[ci] || level > cellMax[ci]) continue;
      const v00 = Vg[j * NX + i], v10 = Vg[j * NX + i + 1];
      const v11 = Vg[(j + 1) * NX + i + 1], v01 = Vg[(j + 1) * NX + i];
      const xa = gx(i), xb = gx(i + 1);
      let t;
      _ok[0] = (v00 - level) * (v10 - level) < 0;
      if (_ok[0]) { t = (level - v00) / (v10 - v00); _px[0] = xa + (xb - xa) * t; _pz[0] = za; }
      _ok[1] = (v10 - level) * (v11 - level) < 0;
      if (_ok[1]) { t = (level - v10) / (v11 - v10); _px[1] = xb; _pz[1] = za + (zb - za) * t; }
      _ok[2] = (v11 - level) * (v01 - level) < 0;
      if (_ok[2]) { t = (level - v11) / (v01 - v11); _px[2] = xb + (xa - xb) * t; _pz[2] = zb; }
      _ok[3] = (v01 - level) * (v00 - level) < 0;
      if (_ok[3]) { t = (level - v01) / (v00 - v01); _px[3] = xa; _pz[3] = zb + (za - zb) * t; }

      let cnt = 0;
      for (let e = 0; e < 4; e++) if (_ok[e]) cnt++;
      let pairs = null;
      if (cnt === 2) {
        const v = [];
        for (let e = 0; e < 4; e++) if (_ok[e]) v.push(e);
        pairs = [[v[0], v[1]]];
      } else if (cnt === 4) {
        const centre = (v00 + v10 + v11 + v01) * 0.25;
        pairs = centre > level ? [[0, 1], [2, 3]] : [[0, 3], [1, 2]];
      }
      if (!pairs) continue;
      for (let p = 0; p < pairs.length; p++) {
        const e1 = pairs[p][0], e2 = pairs[p][1];
        if (n + 2 > cap) return n;
        arr[3 * n] = _px[e1]; arr[3 * n + 1] = y; arr[3 * n + 2] = _pz[e1];
        if (levArr) levArr[n] = level; n++;
        arr[3 * n] = _px[e2]; arr[3 * n + 1] = y; arr[3 * n + 2] = _pz[e2];
        if (levArr) levArr[n] = level; n++;
      }
    }
  }
  return n;
}

function updateContours() {
  cCount = 0;
  for (const L of LEVELS) {
    if (Math.abs(L) < 1e-6) continue;
    cCount = marchLevel(L, cPos, cLev, cCount, L * morph, MAXV);
  }
  contourGeom.attributes.position.needsUpdate = true;
  contourGeom.setDrawRange(0, cCount);
  contourGeom.computeBoundingSphere();

  zCount = marchLevel(0, zPos, null, 0, 0, ZMAX);
  zeroGeom.attributes.position.needsUpdate = true;
  zeroGeom.setDrawRange(0, zCount);
  zeroGeom.computeBoundingSphere();
}

function rescaleLines() {
  for (let n = 0; n < cCount; n++) cPos[3 * n + 1] = cLev[n] * morph;
  contourGeom.attributes.position.needsUpdate = true;
}

/* ── bounding box wireframe ──────────────────────────────────────────────── */
const boxEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(6.4, 2.8, 5.2)),
  new THREE.LineBasicMaterial({ color: 0x9a9a9a })
);
scene.add(boxEdges);

/* ── label leader lines ──────────────────────────────────────────────────── */
const leadPos = new Float32Array(6 * 3);
const leadGeom = new THREE.BufferGeometry();
leadGeom.setAttribute('position', new THREE.BufferAttribute(leadPos, 3));
const leaders = new THREE.LineSegments(
  leadGeom, new THREE.LineBasicMaterial({ color: 0x9aa2ab })
);
scene.add(leaders);

/* ── build ───────────────────────────────────────────────────────────────── */
computeField();
updateSurface();
updateContours();

registerInteractive(surfMesh, {
  title: 'Potential surface V(x, y)',
  tooltip: 'Height = potential. Click for details.',
  body: 'The height of this sheet is the electric potential of two charges carried on conducting spheres of radius a. ' +
        'Near the positive sphere V → +k q/a, giving a steep hill truncated flat at the sphere surface; near the negative ' +
        'sphere V → −k q/a, giving the matching funnel. Far away the two contributions cancel and the sheet flattens to V = 0. ' +
        'The dark rings are equipotentials: where they crowd together, the field E = −∇V is strong.'
});

/* ── camera (pit front-left, peak back-right, ~28° above the sheet) ──────── */
const ISO_VIEW = { projection: 'orthographic', azimuthDeg: 132, elevationDeg: 28, heightFraction: 0.62 };
const TOP_VIEW = { projection: 'orthographic', azimuthDeg: 92, elevationDeg: 88, heightFraction: 0.62 };
setCameraView(ISO_VIEW);

/* ── labels ──────────────────────────────────────────────────────────────── */
const WBG = 'rgba(255,255,255,0.84)';
const labPlus = addLabel('+<i>q</i>', new THREE.Vector3(0, 0, 0),
  { fontSize: '15px', color: '#b0356a', bold: true, background: WBG, offset: [0, -9] });
const labMinus = addLabel('&minus;<i>q</i>', new THREE.Vector3(0, 0, 0),
  { fontSize: '15px', color: '#2f5fa8', bold: true, background: WBG, offset: [0, -9] });
const labCap = addLabel('flat cap = sphere surface', new THREE.Vector3(0, 0, 0),
  { fontSize: '10px', color: '#6b7280', background: WBG, offset: [0, -26] });
const labZero = addLabel('<i>V</i> = 0 sheet', new THREE.Vector3(0, 0, 0),
  { fontSize: '12px', color: '#4e6b86', bold: true, background: WBG, offset: [0, 0] });
const labEqui = addLabel('equipotentials', new THREE.Vector3(0, 0, 0),
  { fontSize: '11px', color: '#1b1b2a', bold: true, background: WBG, offset: [0, -9] });
const ALL_LABELS = [labPlus, labMinus, labCap, labZero, labEqui];

function setSeg(k, ax, ay, az, bx, by, bz) {
  leadPos[6 * k] = ax; leadPos[6 * k + 1] = ay; leadPos[6 * k + 2] = az;
  leadPos[6 * k + 3] = bx; leadPos[6 * k + 4] = by; leadPos[6 * k + 5] = bz;
}

function updateLabels() {
  const capY = CLAMPV * morph;
  const pitY = -CLAMPV * morph;
  const topY = capY + 0.60 * morph;
  const outY = 0.05 + 0.95 * morph;

  labPlus.pos.set(sep / 2, topY + 0.02, 0);
  labMinus.pos.set(-sep / 2, outY, 0);
  labCap.pos.set(sep / 2, topY + 0.02, 0);
  labZero.pos.set(-0.15, 0.02, Z1 + 0.22);

  const ex = sep / 2 + 1.15, ez = 0.95;
  const ey = Math.max(-CLAMPV, Math.min(CLAMPV, fieldAt(ex, ez))) * morph;
  labEqui.pos.set(ex + 0.42, ey + 0.55 * morph + 0.16, ez + 0.3);

  setSeg(0, sep / 2, capY, 0, sep / 2, topY, 0);
  setSeg(1, -sep / 2, pitY + 0.02, 0, -sep / 2, outY, 0);
  setSeg(2, ex, ey, ez, ex + 0.42, ey + 0.55 * morph + 0.16, ez + 0.3);
  leadGeom.attributes.position.needsUpdate = true;
  leadGeom.computeBoundingSphere();

  const vis = morph > 0.3;
  leaders.visible = annotations && vis;
  for (const L of ALL_LABELS) L.div.style.display = annotations ? '' : 'none';
  if (annotations) {
    labCap.div.style.opacity = morph > 0.6 ? '1' : '0';
    labEqui.div.style.opacity = vis ? '1' : '0';
    labPlus.div.style.opacity = vis ? '1' : '0.35';
    labMinus.div.style.opacity = vis ? '1' : '0.35';
  }
}
updateLabels();

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const elBal = document.getElementById('chargeBalance');
const elSep = document.getElementById('chargeSeparation');
const valBal = document.getElementById('valBal');
const valSep = document.getElementById('valSep');
const btnSurf = document.getElementById('modeSurf');
const btnMap = document.getElementById('modeMap');
const chkLab = document.getElementById('showLabels');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function refreshAll() {
  computeField();
  updateSurface();
  updateContours();
  updateLabels();
}
function syncReadouts() {
  valBal.textContent = qMinus.toFixed(2);
  valSep.textContent = sep.toFixed(2);
}
syncReadouts();

let tween = null;

elBal.addEventListener('input', () => {
  qMinus = parseFloat(elBal.value); tween = null;
  syncReadouts(); refreshAll();
});
elSep.addEventListener('input', () => {
  sep = parseFloat(elSep.value); tween = null;
  syncReadouts(); refreshAll();
});
chkLab.addEventListener('change', () => {
  annotations = chkLab.checked;
  updateLabels();
});

function setMode(name, moveCamera) {
  const flat = (name === 'Contour map only');
  morphTarget = flat ? 0 : 1;
  btnSurf.classList.toggle('active', !flat);
  btnMap.classList.toggle('active', flat);
  boxEdges.visible = !flat;
  if (moveCamera !== false) setCameraView(flat ? TOP_VIEW : ISO_VIEW);
}
btnSurf.addEventListener('click', () => setMode('Surface + contours'));
btnMap.addEventListener('click', () => setMode('Contour map only'));

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1. Equal and opposite charges',
    narration: 'Height is electric potential. The right charge is positive, raising a steep narrow peak; the left charge is equal and negative, carving a matching funnel. Both are truncated at the conducting-sphere surface.',
    state: { chargeBalance: -1, chargeSeparation: 2.6, viewMode: 'Surface + contours' }
  },
  {
    title: '2. Read the contours',
    narration: 'Flatten to the contour map. The rings crowd where the surface was steepest, right at each charge, and spread far apart out on the flat sheet — close contours mean a strong field.',
    state: { chargeBalance: -1, chargeSeparation: 2.6, viewMode: 'Contour map only' }
  },
  {
    title: '3. Bring the charges together',
    narration: 'Reducing the separation pulls hill and trough close; the sheet between them tilts sharply and the loops elongate, showing the intense field in the gap between the spheres.',
    state: { chargeBalance: -1, chargeSeparation: 1, viewMode: 'Surface + contours' }
  },
  {
    title: '4. Unbalance the charges',
    narration: 'Weakening the negative charge shallows the trough while the peak keeps its height, and the zero-potential line shifts toward the weaker charge — sign and magnitude both read directly off the relief.',
    state: { chargeBalance: -0.4, chargeSeparation: 2.6, viewMode: 'Surface + contours' }
  }
];
let stepIdx = 0, playTimer = null;

function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  stepText.textContent = s.narration;
  setMode(s.state.viewMode);
  tween = {
    b0: qMinus, s0: sep,
    b1: s.state.chargeBalance, s1: s.state.chargeSeparation,
    t0: performance.now(), dur: 850
  };
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
const btnPlay = document.getElementById('stepPlay');
btnPlay.addEventListener('click', () => {
  if (playTimer) {
    clearInterval(playTimer); playTimer = null;
    btnPlay.textContent = 'Play'; btnPlay.classList.remove('active');
  } else {
    btnPlay.textContent = 'Stop'; btnPlay.classList.add('active');
    goToStep(stepIdx + 1);
    playTimer = setInterval(() => goToStep(stepIdx + 1), 5200);
  }
});
goToStep(0);

/* ── tween / morph loop (separate from the scaffold's animate) ───────────── */
function figLoop() {
  requestAnimationFrame(figLoop);

  if (tween) {
    const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = u * u * (3 - 2 * u);
    qMinus = tween.b0 + (tween.b1 - tween.b0) * e;
    sep = tween.s0 + (tween.s1 - tween.s0) * e;
    elBal.value = qMinus; elSep.value = sep;
    syncReadouts(); refreshAll();
    if (u >= 1) tween = null;
  }

  if (Math.abs(morph - morphTarget) > 0.002) {
    morph += (morphTarget - morph) * 0.14;
    updateSurface(); rescaleLines(); updateLabels();
  } else if (morph !== morphTarget) {
    morph = morphTarget;
    updateSurface(); rescaleLines(); updateLabels();
  }
}
figLoop();
